<script setup lang="ts">
import { modelText, type ObservationContext, type Station, type Page, type CommandResult } from '~/utils/types'
import { ApiFailure } from '~/composables/useApi'
const api=useApi();const {courier,actor}=useSession();const route=useRoute();const documentId=ref(String(route.query.document_id||''));const stationId=ref('');const stations=ref<Station[]>([]);const context=ref<ObservationContext>();const step=ref('');const photoId=ref('');const reason=ref('');const physical=ref(false);const loading=ref(false);const saving=ref(false);const error=ref<unknown>();const message=ref('');const operation=ref<CommandResult>();const conflicted=ref(false);let generation=0
const assigned=computed(()=>stations.value.filter(s=>actor.value?.station_ids.includes(s.id)))
const gap=computed(()=>!!context.value&&(!step.value||step.value!==context.value.current_route_step_id))
function invalidate(){generation++;loading.value=false;context.value=undefined;step.value='';photoId.value='';physical.value=false;conflicted.value=false;message.value=''}
async function load(){if(!courier.value)return;const run=++generation;context.value=undefined;step.value='';photoId.value='';physical.value=false;conflicted.value=false;loading.value=true;error.value=undefined;message.value='';try{const result=await api.get<ObservationContext>(`/courier/observation-context?document_id=${encodeURIComponent(documentId.value.trim())}&station_id=${encodeURIComponent(stationId.value)}`);if(run!==generation)return;context.value=result;if(result.route_steps.length===1)step.value=result.route_steps[0]!.step_id}catch(e){if(run===generation)error.value=e}finally{if(run===generation)loading.value=false}}
async function submit(){const c=context.value;if(!c||!c.can_observe||!photoId.value||!reason.value.trim()||!physical.value||conflicted.value||(c.route_steps.length&&!step.value))return;saving.value=true;error.value=undefined;try{const result=await api.command<CommandResult&{reconciliation_status:string}>(`/documents/${c.document_id}/observations`,{expected_version:c.document_version,observed_station_id:stationId.value,proposed_route_step_id:step.value||null,evidence_upload_ids:[photoId.value],reason:reason.value.trim(),physical_presence_confirmed:true});operation.value=result.process_sync_status==='APPLIED'?undefined:result;message.value=result.reconciliation_status==='REQUIRES_REVIEW'?'บันทึกตำแหน่งและช่องว่างการนำส่งแล้ว งานถูกพักรอผู้มีสิทธิ์ตรวจสอบข้อยกเว้น':'บันทึกการพบหนังสือแล้ว ไม่เปลี่ยนผู้ถือครองหรือยืนยันรับแทนหน่วยงาน';context.value=undefined;photoId.value='';physical.value=false;reason.value=''}catch(e){error.value=e;conflicted.value=e instanceof ApiFailure&&e.status===409}finally{saving.value=false}}
onMounted(async()=>{if(!courier.value)return;try{stations.value=(await api.get<Page<Station>>('/stations')).items;stationId.value=assigned.value[0]?.id||''}catch(e){error.value=e}})
onBeforeUnmount(()=>generation++)
</script>
<template>
  <div class="page-head"><div><h1>บันทึกพบหนังสือจริง</h1><p>สำหรับ Model A เมื่อพบหนังสือที่ Station ที่คุณมีสิทธิ์ บันทึกตำแหน่งจากรูปจริงโดยไม่เดาผู้นำส่งหรือเวลาของช่วงที่ไม่มีหลักฐาน</p></div></div><Feedback v-if="!courier" :error="new Error('บัญชีนี้ไม่มีสิทธิ์ Courier')" />
  <template v-else><Feedback :error="error" :message="message" /><OperationStatus v-if="operation" :operation-id="operation.operation_id" :sync-status="operation.process_sync_status" @applied="operation=undefined" />
    <form class="panel" @submit.prevent="load"><h2>ค้นหาหนังสือที่พบ</h2><div class="form-grid"><div class="field"><label for="observation-document">เลขอ้างอิงระบบของหนังสือ</label><input id="observation-document" data-testid="observation-document" v-model="documentId" required :disabled="saving" @input="invalidate" /></div><div class="field"><label for="observation-station">Station ที่พบจริง</label><select id="observation-station" data-testid="observation-station" v-model="stationId" required :disabled="saving" @change="invalidate"><option disabled value="">เลือก Station</option><option v-for="s in assigned" :key="s.id" :value="s.id">{{s.name}}</option></select></div></div><button data-testid="observation-load" class="button" :disabled="loading||saving||!!operation||!stationId||!documentId.trim()">{{loading?'กำลังตรวจสิทธิ์และเส้นทาง…':'ตรวจหนังสือและเส้นทาง'}}</button></form>
    <form v-if="context" class="panel" @submit.prevent="submit"><h2>หลักฐานการพบหนังสือ</h2><div class="actions"><span class="status">{{modelText(context.tracking_mode)}}</span><StatusTag :value="context.business_state" /><StatusTag :value="context.process_sync_status" /></div><p class="hint break">หนังสืออ้างอิง {{context.document_id}} · เวอร์ชัน {{context.document_version}}</p>
      <OperationStatus v-if="context.process_sync_status!=='APPLIED'" :operation-id="context.latest_operation_id" :sync-status="context.process_sync_status" @applied="load" />
      <p v-if="!context.can_observe" class="notice sync-notice">สถานะนี้ยังบันทึกการพบไม่ได้ เช่น มีผู้ถือครอง อยู่ระหว่างประสาน workflow จบการติดตาม หรือรอแก้ข้อยกเว้น โปรดตรวจสถานะล่าสุด</p>
      <template v-else><div v-if="context.route_steps.length" class="field inline-reason"><label for="observation-step">จุดในเส้นทางที่พบจริง</label><select id="observation-step" data-testid="observation-step" v-model="step" required :disabled="saving" @change="physical=false"><option disabled value="">เลือกจุดที่แน่นอนในเส้นทาง</option><option v-for="s in context.route_steps" :key="s.step_id" :value="s.step_id">จุดที่ {{s.sequence+1}}{{s.step_id===context.current_route_step_id?' · จุดปัจจุบัน':''}} · {{stations.find(station=>station.id===s.station_id)?.name||s.station_id}}</option></select><p class="hint">Station เดียวกันอาจปรากฏหลายครั้ง ต้องระบุจุดจริง ห้ามใช้จุดต้นทางแทนจุดรับคืน</p></div><p v-else class="notice sync-notice">Station นี้อยู่นอกเส้นทางที่ตรึงไว้ ระบบจะเปิดข้อยกเว้นและพักงานเพื่อให้ผู้มีสิทธิ์ตรวจสอบ</p><p v-if="gap&&context.route_steps.length" class="notice sync-notice">ตำแหน่งนี้ต่างจากจุดปัจจุบัน จะบันทึกช่องว่างการนำส่งและพัก workflow รอแก้ข้อยกเว้น ไม่ข้ามไป Check รับโดยอัตโนมัติ</p>
        <EvidencePhoto :key="`${context.document_id}:${stationId}:${context.document_version}`" :station-id="stationId" :disabled="saving" @ready="photoId=$event" @changed="photoId=''" />
        <div class="field inline-reason"><label for="observation-reason">รายละเอียดและเหตุผลที่บันทึกพบ</label><textarea id="observation-reason" data-testid="observation-reason" v-model="reason" required maxlength="1000" :disabled="saving" /></div><label class="confirmation"><input data-testid="observation-physical" v-model="physical" type="checkbox" :disabled="saving" />ฉันพบหนังสือจริงรายการนี้ที่ Station และจุดในเส้นทางที่ระบุ</label><p v-if="conflicted" class="hint">ข้อมูลเปลี่ยนแล้ว โปรดตรวจหนังสือและเส้นทางล่าสุดก่อนยืนยันอีกครั้ง</p><button data-testid="observation-submit" class="button primary actions" :disabled="saving||conflicted||!photoId||!reason.trim()||!physical||(!!context.route_steps.length&&!step)">{{saving?'กำลังบันทึก…':'บันทึกการพบหนังสือ'}}</button>
      </template>
    </form>
  </template>
</template>
